 if(!(best<old_sq)||!r.station_allowed(b.core.model,r.path,best_s,1e-12))continue;const auto certificate=b.core.model.project_rs(l,best_s,best_row);if(!certificate.valid)continue;const auto verified=b.core.model.predict_for_al(l,best_s,certificate.row,pp.data());const double verified_sq=std::pow(verified.uv[0]-r.uv[0],2)+std::pow(verified.uv[1]-r.uv[1],2);if(!verified.arithmetic_valid||verified.physical_status!=DomainStatus::kValid||!(verified_sq<old_sq)||!b.core.model.visibility(l,best_s,certificate.row,pp.data()).visible())continue;
 b.core.station[i]=best_s;b.core.row[i]=certificate.row;moved[i]=1;++changed;{std::lock_guard<std::mutex>lock(mutex);sum_old+=old_sq;sum_new+=verified_sq;largest_before=std::max(largest_before,std::sqrt(old_sq));largest_after=std::max(largest_after,std::sqrt(verified_sq));ledger<<eventio::Json({{"joint_row",i},{"native_pts",r.pts},{"source_row_id",r.source_row_id},{"material",r.material},{"path_unchanged",r.path},{"old_station",old_s},{"new_station",best_s},{"old_row",old_row},{"new_row",certificate.row},{"old_error_sq",old_sq},{"new_error_sq",verified_sq},{"original_source_uv",r.uv},{"source_UV_or_identity_changed",false}}).dump()<<'\n';}
