 const auto state=b.capture_state();const auto after=b.evaluate_constraints(state);auto merit=[&](const ConstraintValues&v){long double result=budget+.5L;for(double g:v.g){const double z=inequality_residual(g,0.,cp.outer.rho);result+=.5L*z*z;}for(double h:v.h){const double z=equality_residual(h,0.,cp.outer.rho);result+=.5L*z*z;}return double(result);};const double initial_merit=merit(before),final_merit=merit(after);if(final_merit>initial_merit+1e-8)throw std::runtime_error("coordinate candidates failed complete unchanged original AL acceptance");
